 * How long a row waits at most, empty, for the name a run was started with to arrive ({@link awaitingName}).
 *
 * A name comes about a second after Start (the daemon's naming session waits for it), a few
 * seconds when the run asks on its own, and the ask gives up after a minute; past that the
 * row has waited long enough and shows what the person typed instead.
 */
export const NAMING_WAIT_MS = 60_000

/**
 * Whether a row should wait, rather than put the person's whole prompt where the name is going.
 *
 * A run is named moments after it starts, so a row that opens with the prompt swaps it for the name
 * a second later — the one flicker in a list that is otherwise still. Claude Code on the web has the
 * name from the first frame because it makes one server-side; ours is a model's answer, so the row
 * holds the place instead of filling it with something it is about to throw away.
 *
 * Only while the run's card says its name is being asked for ({@link AgentMeta.naming}) and it is at
 * work: naming turned off, a run too old, a run that already has one, a run no name is asked for (a
 * slash command, named from its report at its end) or whose ask ended without one, and a run that
 * ended or waits on the person (which "Waiting on you" and the Human Queue already name) are
 * answered right away.
 */
export function awaitingName(agent: Pick<AgentMeta, 'title' | 'naming' | 'startedAt' | 'status'>, naming: boolean, now = Date.now()): boolean {
  if (!naming || agent.naming !== true || agent.status !== 'running' || agent.title !== undefined) return false
  const started = Date.parse(agent.startedAt)
  return Number.isFinite(started) && now - started < NAMING_WAIT_MS
}

